-- Removing a client/task removes only its incident associations, not the incident.
-- Replace existing keys by column, including keys generated by Hibernate.
DO $$
DECLARE
    relation record;
    existing_fk record;
BEGIN
    FOR relation IN
        SELECT * FROM (VALUES
            ('support_incident_task_link', 'task_id', 'task', 'fk_support_incident_task_link_task'),
            ('support_incident_clients', 'client_id', 'client', 'fk_support_incident_clients_client')
        ) AS relations(table_name, column_name, parent_table, constraint_name)
    LOOP
        FOR existing_fk IN
            SELECT c.conname
            FROM pg_constraint c
            JOIN pg_attribute a ON a.attrelid = c.conrelid
                               AND c.conkey = ARRAY[a.attnum]
            WHERE c.contype = 'f'
              AND c.conrelid = relation.table_name::regclass
              AND c.confrelid = relation.parent_table::regclass
              AND a.attname = relation.column_name
        LOOP
            EXECUTE format('ALTER TABLE %I DROP CONSTRAINT %I', relation.table_name, existing_fk.conname);
        END LOOP;

        EXECUTE format(
            'ALTER TABLE %I ADD CONSTRAINT %I FOREIGN KEY (%I) REFERENCES %I(id) ON DELETE CASCADE',
            relation.table_name, relation.constraint_name, relation.column_name, relation.parent_table
        );
    END LOOP;
END
$$;
